INSERT INTO `opds` VALUES (1,'Inspektorat','inspektorat','INSPEKTORAT','Dr. RUSITO, S.Sos, M.Si','Inspektorat Daerah merupakan unsur pengawas penyelenggaraan pemerintahan daerah yang memiliki tugas utama melakukan pengawasan terhadap pelaksanaan urusan pemerintahan di lingkungan pemerintah daerah. Lembaga ini bertanggung jawab langsung kepada Kepala Daerah, serta berperan penting dalam memastikan terselenggaranya pemerintahan yang efektif, efisien, bersih, dan bebas dari praktik korupsi, kolusi, dan nepotisme (KKN).\n','diskominfosp@lebakkab.go.id','02525123456','https://inspektorat.lebakkab.go.id/','jl abdinegara no 3',NULL,'opd/gujoub6p7SmeHUSzjgf9FTbgXXZ6O0-metaMTY0ODQ1MjQ5MF9hNmJlMTlkMTIwMjk0YjE5NjBkNy5wbmc=-.png','opd/G7f4uXb4tUW2cJxUyN0gfYyBT7t077-metadGFtcGFrMy5qcGc=-.jpg','<iframe src=\"https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3965.252993328361!2d106.2425515749916!3d-6.361293393628772!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2e4216d6650993ab%3A0x92291f2d5a85bb38!2sDiskominfo%20Kabupaten%20Lebak!5e0!3m2!1sid!2sid!4v1754276049935!5m2!1sid!2sid\" width=\"600\" height=\"450\" style=\"border:0;\" allowfullscreen=\"\" loading=\"lazy\" referrerpolicy=\"no-referrer-when-downgrade\"></iframe>',0,1,0,'2025-08-03 19:54:32','2025-10-14 21:32:14',NULL),(2,'Badan Pendapatan Daerah','badan-pendapatan-daerah','BAPENDA',NULL,'	Badan Pendapatan Daerah','bapenda@lebakkab.go.id','025233344455','https://bapenda.lebakkab.go.id','jl rangkasbitng',NULL,'opd/j7JCOJxrD7YqbR8IfBdxFOAYB4JBTc-metaMTY0ODQ1MjQ5MF9hNmJlMTlkMTIwMjk0YjE5NjBkNy5wbmc=-.png','opd/kantor bapenda lebak.png','<iframe src=\"https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3965.3684160881194!2d106.23650717576598!3d-6.346315862091651!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2e42173a802c28ad%3A0xcc53fd92d86ae81b!2sBadan%20Pendapatan%20Daerah%20Kabupaten%20Lebak!5e0!3m2!1sid!2sid!4v1754276281997!5m2!1sid!2sid\" width=\"600\" height=\"450\" style=\"border:0;\" allowfullscreen=\"\"