INSERT INTO `pejabats` VALUES (1,NULL,'bupati','H. Mochamad Hasbi Asyidiki Jayabaya, S.H,','Bupati Lebak','0123456789','Bupati kabupaten Lebak','pejabat/bupati_hasbi.png','Mewujudkan Kabupaten Lebak yang Maju, Mandiri, dan Sejahtera','2025-2030','<p>Data belum di input</p>','<p>2008 - 2014 : Direktur PT. Giri Jaya Putra<br>2010 - 2014 : Ketua KONI Kabupaten Lebak<br>2014 - 2019 : Anggota DPR-RI<br>2019 - 2024 : Anggota DPR-RI<br>2025 - Sekarang: Bupati Kabupaten Lebak</p>',NULL,1,1,'2026-07-12 18:43:05','2026-07-13 02:10:27'),(2,NULL,'wakil_bupati','Ir. H. Amir Hamzah, M.Si','Wakil Bupati Lebak','-','-','pejabat/wakil_amir.png','Bersama Membangun Lebak yang Lebih Baik','2025-2030','<p>Belum di inputkan</p>','<p>Amir Hamzah merupakan mantan <a href=\"https://id.wikipedia.org/wiki/Aparatur_Sipil_Negara\">Aparatur Sipil Negara</a> dengan karier yang cukup moncer. Ia mengawali kariernya dengan menjabat sebagai Pelaksana Bagian Ekonomi Sekretariat Daerah <a href=\"https://id.wikipedia.org/wiki/Kabupaten_Lebak\">Kabupaten Lebak</a> pada tahun <a href=\"https://id.wikipedia.org/wiki/1993\">1993</a>, Sekretaris Pribadi <a href=\"https://id.wikipedia.org/wiki/Bupati_Lebak\">Bupati Lebak</a> (1993–1998), Kepala Bidang Data dan Penelitian Bappeda <a href=\"https://id.wikipedia.org/wiki/Kabupaten_Lebak\">Kabupaten Lebak</a> (1998–2000), Kepala Bidang Ekonomi Bappeda <a href=\"https://id.wikipedia.org/wiki/Kabupaten_Lebak\">Kabupaten Lebak</a> (2000–2003), Kepala Bagian Tata Usaha Dinas Inkosbudpar (2003–2004), Staf Ahli Khusus <a href=\"https://id.wikipedia.org/wiki/Bupati_Lebak\">Bupati Lebak</a> (2004), Kepala Bagian Program Sekretariat Daerah <a href=\"https://id.wikipedia.org/wiki/Kabupaten_Lebak\">Kabupaten Lebak</a> (2004–2005), Plt. Direktur Lebak Niaga (2006), Asisten Daerah III <a href=\"https://id.wikipedia.org/wiki/Kabupaten_Lebak\">Kabupaten Lebak</a> (2005–2006), Kepala Bappeda <a href=\"https://id.wikipedia.org/wiki/Kabupaten_Lebak\">Kabupaten Lebak</a> (2006–2008). Pada tahun <a href=\"https://id.wikipedia.org/wiki/Pemilihan_umum_Bupati_Lebak_2008\">2008</a>, ia berhasil memenangkan Pilkada Lebak dan terpilih sebagai <a href=\"https://id.wikipedia.org/wiki/Daftar_Wakil_Bupati_Lebak\">Wakil Bupati Lebak</a> mendampingi <a href=\"https://id.wikipedia.org/wiki/Mulyadi_Jayabaya\">Mulyadi Jayabaya</a> untuk masa jabatan 2008–2013.</p><p><br><br></p>',NULL,2,1,'2026-07-12 18:43:06','2026-07-13 02:20:37'),(3,NULL,'kepala_opd','Hj. Anik Sakinah, M.Si','Kepala DInas','068974521232','Kepala Dinas',NULL,NULL,NULL,NULL,NULL,NULL,3,1,'2026-07-20 04:26:11','2026-07-20 04:33:28');
